package ua.edu.teacherlicence.achievement.model;

import lombok.Getter;

@Getter
public enum AchievementType {

    PP_1_PUBLICATIONS(1, "Наявність не менше п'яти публікацій у періодичних наукових виданнях, що включені до переліку фахових видань України, до наукометричних баз, зокрема Scopus, Web of Science Core Collection"),
    PP_2_PATENTS(2, "Наявність одного патенту на винахід або п'яти деклараційних патентів на винахід чи корисну модель, включаючи секретні, або наявність не менше п'яти свідоцтв про реєстрацію авторського права на твір"),
    PP_3_TEXTBOOK(3, "Наявність виданого підручника чи навчального посібника (включаючи електронні) або монографії загальним обсягом не менше 5 авторських аркушів, у співавторстві не менше 1,5 авторського аркуша на кожного"),
    PP_4_METHODICAL(4, "Наявність виданих навчально-методичних посібників/посібників для самостійної роботи, електронних курсів на освітніх платформах, конспектів лекцій/практикумів/методичних вказівок/рекомендацій загальною кількістю три найменування"),
    PP_5_DISSERTATION(5, "Захист дисертації на здобуття наукового ступеня"),
    PP_6_SUPERVISION(6, "Наукове керівництво (консультування) здобувача, який одержав документ про присудження наукового ступеня"),
    PP_7_ATTESTATION(7, "Участь в атестації наукових кадрів як офіційного опонента або члена постійної спеціалізованої вченої ради, або члена не менше трьох разових спеціалізованих вчених рад"),
    PP_8_EDITORIAL(8, "Виконання функцій наукового керівника або відповідального виконавця наукової теми (проекту), або головного редактора/члена редакційної колегії/експерта (рецензента) наукового видання, включеного до переліку фахових видань або іноземного видання, що індексується в бібліографічних базах"),
    PP_9_EXPERT_COUNCIL(9, "Робота у складі експертної ради з питань проведення експертизи дисертацій МОН або у складі галузевої експертної ради як експерта НАЗЯВО, або у складі Акредитаційної комісії, або НМР/науково-методичних комісій з вищої освіти МОН, наукових/експертних рад органів державної влади, або комісій Державної служби якості освіти"),
    PP_10_INTERNATIONAL(10, "Участь у міжнародних наукових та/або освітніх проектах, залучення до міжнародної експертизи, наявність звання «суддя міжнародної категорії»"),
    PP_11_CONSULTING(11, "Наукове консультування підприємств, установ, організацій не менше трьох років, що здійснювалося на підставі договору із закладом вищої освіти (науковою установою)"),
    PP_12_APPROBATION(12, "Наявність апробаційних та/або науково-популярних, та/або консультаційних (дорадчих), та/або науково-експертних публікацій з наукової або професійної тематики загальною кількістю не менше п'яти публікацій"),
    PP_13_FOREIGN_LANGUAGE(13, "Проведення навчальних занять із спеціальних дисциплін іноземною мовою (крім дисциплін мовної підготовки) в обсязі не менше 50 аудиторних годин на навчальний рік"),
    PP_14_STUDENT_OLYMPIAD(14, "Керівництво студентом, який зайняв призове місце на I або II етапі Всеукраїнської студентської олімпіади (конкурсу наукових робіт), або робота у складі оргкомітету/журі, або керівництво студентським науковим гуртком/проблемною групою; мистецькі конкурси, спортивні змагання"),
    PP_15_SCHOOL_OLYMPIAD(15, "Керівництво школярем, який зайняв призове місце III-IV етапу Всеукраїнських учнівських олімпіад або II-III етапу конкурсів-захистів науково-дослідницьких робіт учнів МАН; участь у журі цих заходів"),
    PP_16_COMBAT_VETERAN(16, "Наявність статусу учасника бойових дій (для вищих військових навчальних закладів, закладів вищої освіти із специфічними умовами навчання, військових навчальних підрозділів закладів вищої освіти)"),
    PP_17_UN_PEACEKEEPING(17, "Участь у міжнародних операціях з підтримання миру і безпеки під егідою Організації Об'єднаних Націй"),
    PP_18_NATO_EXERCISES(18, "Участь у міжнародних військових навчаннях (тренуваннях) за участю збройних сил країн — членів НАТО"),
    PP_19_PROFESSIONAL_ASSOCIATIONS(19, "Діяльність за спеціальністю у формі участі у професійних та/або громадських об'єднаннях"),
    PP_20_PRACTICAL_EXPERIENCE(20, "Досвід практичної роботи за спеціальністю не менше п'яти років (крім педагогічної, науково-педагогічної, наукової діяльності)");

    private final int number;
    private final String description;

    AchievementType(int number, String description) {
        this.number = number;
        this.description = description;
    }

    public static AchievementType fromNumber(int number) {
        for (AchievementType type : values()) {
            if (type.number == number) {
                return type;
            }
        }
        return null;
    }
}
